CREATE TABLE public.analysis_drill_enrollments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,sport text NOT NULL CHECK(sport IN ('baseball','softball')),category text NOT NULL CHECK(category IN ('hitting','pitching','throwing','fielding','baserunning')),drill_id text NOT NULL,video_id uuid NOT NULL REFERENCES public.videos(id),issue_key text NOT NULL,fault_key text,goal_label text,observed_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,sport,category,issue_key),CHECK(fault_key IS NOT NULL OR goal_label IS NOT NULL));
GRANT SELECT ON public.analysis_drill_enrollments TO authenticated;
GRANT ALL ON public.analysis_drill_enrollments TO service_role;
ALTER TABLE public.analysis_drill_enrollments ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own analysis drill rotation" ON public.analysis_drill_enrollments FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.analysis_drill_safety_revision(p_user uuid,p_date date) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('context',(SELECT to_jsonb(c) FROM public.athlete_context c WHERE user_id=p_user),'profile',(SELECT jsonb_build_object('dob',date_of_birth,'positions',positions) FROM public.profiles WHERE id=p_user),'settings',(SELECT to_jsonb(s) FROM public.athlete_mpi_settings s WHERE user_id=p_user),'logs',coalesce((SELECT jsonb_agg(to_jsonb(d) ORDER BY d.entry_date) FROM public.athlete_daily_log d WHERE user_id=p_user AND entry_date=p_date),'[]'::jsonb),'gear',coalesce((SELECT jsonb_agg(to_jsonb(g) ORDER BY g.created_at) FROM public.athlete_equipment_context g WHERE user_id=p_user),'[]'::jsonb),'memory',coalesce((SELECT jsonb_agg(to_jsonb(m) ORDER BY m.created_at) FROM public.athlete_equipment_memory m WHERE user_id=p_user AND (scope='always' OR plan_date=p_date)),'[]'::jsonb),'games',coalesce((SELECT jsonb_agg(to_jsonb(g) ORDER BY g.id) FROM public.gp_games g WHERE user_id=p_user AND game_date BETWEEN p_date AND p_date+1),'[]'::jsonb),'calendar',coalesce((SELECT jsonb_agg(to_jsonb(e) ORDER BY e.id) FROM public.calendar_events e WHERE user_id=p_user AND event_date BETWEEN p_date AND p_date+1),'[]'::jsonb),'arm',coalesce((SELECT jsonb_agg(to_jsonb(a) ORDER BY a.id) FROM public.arm_ledger_entries a WHERE user_id=p_user AND entry_date BETWEEN p_date-365 AND p_date),'[]'::jsonb),'subscription',coalesce((SELECT jsonb_agg(to_jsonb(s) ORDER BY s.id) FROM public.subscriptions s WHERE user_id=p_user),'[]'::jsonb),'readiness',coalesce((SELECT jsonb_agg(to_jsonb(e) ORDER BY e.event_id) FROM public.asb_events e WHERE athlete_id=p_user AND topic_id='behavioral.readiness' AND occurred_at>=p_date::timestamptz AND occurred_at<(p_date+1)::timestamptz),'[]'::jsonb)); $$;
REVOKE ALL ON FUNCTION public.analysis_drill_safety_revision(uuid,date) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.analysis_drill_safety_revision(uuid,date) TO service_role;
CREATE OR REPLACE FUNCTION public.wk_analysis_drill_atomic(p_user uuid,p_date date,p_id uuid,p_sport text,p_modality text,p_index integer,p_expected jsonb,p_replacement jsonb,p_enrollment jsonb,p_expected_updated timestamptz,p_safety jsonb,p_warnings jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE s public.athlete_plan_snapshots; b integer; result jsonb; v public.videos; reason text;
BEGIN
 PERFORM public.wk_lock_plan_day(p_user,p_date);
 IF p_safety IS DISTINCT FROM public.analysis_drill_safety_revision(p_user,p_date) THEN RAISE EXCEPTION 'Safety facts changed'; END IF;
 SELECT * INTO s FROM public.athlete_plan_snapshots WHERE id=p_id AND user_id=p_user AND plan_date=p_date AND sport=p_sport FOR UPDATE;
 IF NOT FOUND OR s.updated_at IS DISTINCT FROM p_expected_updated THEN RAISE EXCEPTION 'Plan changed'; END IF;
 SELECT * INTO v FROM public.videos WHERE id=(p_enrollment->>'video_id')::uuid AND user_id=p_user AND sport::text=p_sport AND status::text='completed' FOR SHARE;
 IF NOT FOUND OR (v.temporary_until IS NOT NULL AND v.temporary_until<=now()) OR v.module::text<>p_enrollment->>'category' THEN RAISE EXCEPTION 'Analysis unavailable'; END IF;
 IF p_enrollment->>'fault_key' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.analysis_fault_findings WHERE video_id=v.id AND user_id=p_user AND sport=p_sport AND fault_key=p_enrollment->>'fault_key') AND coalesce(v.ai_analysis->'violations_detected'->>(p_enrollment->>'fault_key'),'false')<>'true' THEN RAISE EXCEPTION 'Finding unavailable'; END IF;
 IF p_expected->>'prescriptionOrigin'='owner' OR p_expected->>'ownerDrillId' IS NOT NULL OR p_expected->>'bunt' IS NOT NULL OR coalesce(p_expected->>'stage','drills')<>'drills' THEN RAISE EXCEPTION 'Protected slot'; END IF;
 reason:=p_enrollment->>'because';
 result:=public.wk_swap_block_atomic(p_user,p_date,p_id,p_sport,p_modality,p_index,p_expected,p_replacement,reason,'{}','today');
 INSERT INTO public.analysis_drill_enrollments(user_id,sport,category,drill_id,video_id,issue_key,fault_key,goal_label,observed_at) VALUES(p_user,p_sport,p_enrollment->>'category',p_replacement->>'slug',v.id,p_enrollment->>'issue_key',p_enrollment->>'fault_key',p_enrollment->>'goal_label',v.created_at)
 ON CONFLICT(user_id,sport,category,issue_key) DO UPDATE SET drill_id=excluded.drill_id,video_id=excluded.video_id,fault_key=excluded.fault_key,goal_label=excluded.goal_label,observed_at=excluded.observed_at,created_at=clock_timestamp();
 SELECT * INTO s FROM public.athlete_plan_snapshots WHERE id=p_id;
 SELECT ordinality::integer-1 INTO b FROM jsonb_array_elements(s.payload->'blocks') WITH ORDINALITY WHERE value->>'modality'=p_modality;
 s.payload:=jsonb_set(s.payload,ARRAY['blocks',b::text,'because'],coalesce(s.payload->'blocks'->b->'because','[]'::jsonb)||jsonb_build_array(reason));
 s.payload:=jsonb_set(s.payload,ARRAY['blocks',b::text,'steps'],(SELECT jsonb_agg(to_jsonb((d->>'name')||' — '||(d->>'dosage'))) FROM jsonb_array_elements(s.payload->'blocks'->b->'drills') d));
 UPDATE public.athlete_plan_snapshots SET payload=s.payload,updated_at=clock_timestamp() WHERE id=p_id;
 INSERT INTO public.audit_log(user_id,action,table_name,record_id,metadata) VALUES(p_user,'analysis_drill_add_today','analysis_drill_enrollments',v.id,jsonb_build_object('plan_date',p_date,'drill_id',p_replacement->>'slug','issue_key',p_enrollment->>'issue_key','warnings',p_warnings));
 RETURN jsonb_build_object('saved',true,'payload',s.payload,'drillId',p_replacement->>'slug');
END $$;
REVOKE ALL ON FUNCTION public.wk_analysis_drill_atomic(uuid,date,uuid,text,text,integer,jsonb,jsonb,jsonb,timestamptz,jsonb,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.wk_analysis_drill_atomic(uuid,date,uuid,text,text,integer,jsonb,jsonb,jsonb,timestamptz,jsonb,jsonb) TO service_role;